<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#e30613; --blue:#0067c9; --yellow:#ffd800; --black:#111; --white:#f5f2ea; --grey:#c9c6bd;
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  body{background:var(--white); color:var(--black); font-family:'Archivo',sans-serif; line-height:1.55;}
  .bar{height:22px; background:var(--black);}
  .bar.stripe-red{background:var(--red);}
  .bar.stripe-blue{background:var(--blue);}
  .bar.stripe-yellow{background:var(--yellow);}
  header{display:grid; grid-template-columns:1fr 1fr; min-height:78vh; border-bottom:8px solid var(--black);}
  .hero-art{position:relative; border-right:8px solid var(--black); background:var(--white); overflow:hidden;}
  .composition{position:absolute; inset:0; display:grid; grid-template-columns:2fr 1fr 3fr; grid-template-rows:3fr 1fr 2fr;}
  .composition .cell{border:5px solid var(--black);}
  .cell-red{background:var(--red); grid-column:3; grid-row:1;}
  .cell-blue{background:var(--blue); grid-column:1; grid-row:3;}
  .cell-yellow{background:var(--yellow); grid-column:3; grid-row:3;}
  .cell-white1{background:var(--white); grid-column:1; grid-row:1;}
  .cell-white2{background:var(--white); grid-column:2; grid-row:1;}
  .cell-black1{background:var(--black); grid-column:2; grid-row:2;}
  .cell-white3{background:var(--white); grid-column:1; grid-row:2;}
  .cell-white4{background:var(--white); grid-column:2; grid-row:3;}
  .cell-white5{background:var(--grey); grid-column:3; grid-row:2;}
  @keyframes blockin{from{opacity:0; transform:scale(1.06);} to{opacity:1; transform:scale(1);}}
  .composition .cell{animation:blockin .9s ease both;}
  .cell-red{animation-delay:.1s}.cell-blue{animation-delay:.3s}.cell-yellow{animation-delay:.45s}
  .hero-text{display:flex; flex-direction:column; justify-content:center; padding:clamp(24px,5vw,64px);}
  .kicker{font-family:'IBM Plex Mono',monospace; font-size:.8rem; letter-spacing:.25em; text-transform:uppercase;}
  h1{font-weight:800; font-size:clamp(2rem,4.5vw,3.6rem); line-height:1.05; margin:.35em 0; text-transform:uppercase;}
  .sub{font-size:1.1rem; max-width:38ch;}
  .cta{display:inline-block; margin-top:1.6em; padding:.9em 1.6em; background:var(--black); color:var(--white); text-decoration:none; font-weight:600; letter-spacing:.05em; text-transform:uppercase; font-size:.85rem; border:3px solid var(--black); transition:all .2s;}
  .cta:hover{background:var(--red); border-color:var(--red); color:var(--white);}
  main{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr);}
  section{padding:clamp(28px,5vw,72px);}
  section h2{font-size:.85rem; letter-spacing:.3em; text-transform:uppercase; font-family:'IBM Plex Mono',monospace; border-bottom:5px solid var(--black); padding-bottom:.5em; margin-bottom:1.2em;}
  ul.facts{list-style:none;}
  ul.facts li{display:grid; grid-template-columns:130px 1fr; gap:1em; padding:.6em 0; border-bottom:1px solid var(--grey);}
  ul.facts dt{font-weight:600; text-transform:uppercase; font-size:.75rem; letter-spacing:.1em; color:#555;}
  ul.facts dd{font-size:1rem;}
  .why{background:var(--black); color:var(--white);}
  .why h2{color:var(--yellow); border-color:var(--yellow);}
  .why p{font-size:clamp(1.1rem,2vw,1.5rem); font-weight:400; line-height:1.4;}
